<?php
class Proyecto_lote_model extends CI_Model{
 public function get_by_proyecto($pid,$estado=''){ $this->db->select("l.*,p.producto_precio precio,p.producto_nombre,p.producto_codigo,c.cliente_nombre,CASE WHEN EXISTS(SELECT 1 FROM detalle_venta dv JOIN venta v ON v.venta_id=dv.venta_id WHERE dv.producto_id=l.producto_id AND v.estado_id=1) THEN 'VENDIDO' ELSE l.estado_lote END estado_actual",false)->from('proyecto_lote l')->join('producto p','p.producto_id=l.producto_id')->join('cliente c','c.cliente_id=l.cliente_id','left')->where('l.proyecto_id',$pid); if($estado)$this->db->having('estado_actual',$estado); return $this->db->order_by('l.lote_codigo')->get()->result_array(); }
 public function get_by_id($id){$this->db->select("l.*,p.producto_precio precio,p.producto_nombre,p.producto_codigo,c.cliente_nombre,CASE WHEN EXISTS(SELECT 1 FROM detalle_venta dv JOIN venta v ON v.venta_id=dv.venta_id WHERE dv.producto_id=l.producto_id AND v.estado_id=1) THEN 'VENDIDO' ELSE l.estado_lote END estado_actual",false)->from('proyecto_lote l')->join('producto p','p.producto_id=l.producto_id')->join('cliente c','c.cliente_id=l.cliente_id','left')->where('l.proyecto_lote_id',$id);return $this->db->get()->row_array();}
 public function existe_codigo($pid,$cod,$id=0){$this->db->where(array('proyecto_id'=>$pid,'lote_codigo'=>$cod));if($id)$this->db->where('proyecto_lote_id <>',$id);return $this->db->count_all_results('proyecto_lote')>0;}
 public function add($p){$this->db->insert('proyecto_lote',$p);return $this->db->insert_id();} public function update($id,$p){$this->db->where('proyecto_lote_id',$id);return $this->db->update('proyecto_lote',$p);}
 public function historial_add($id,$a,$d,$u){return $this->db->insert('proyecto_lote_historial',array('proyecto_lote_id'=>$id,'accion'=>$a,'detalle'=>$d,'usuario_id'=>$u,'fecha_hora'=>date('Y-m-d H:i:s')));} public function historial($id){return $this->db->order_by('historial_id','desc')->get_where('proyecto_lote_historial',array('proyecto_lote_id'=>$id))->result_array();}
 public function reserva_add($p){$this->db->insert('proyecto_lote_reserva',$p);return $this->db->insert_id();} public function cancelar_reservas_activas($id){$this->db->where(array('proyecto_lote_id'=>$id,'estado'=>'ACTIVA'));return $this->db->update('proyecto_lote_reserva',array('estado'=>'CANCELADA'));} public function reservas($id){return $this->db->order_by('reserva_id','desc')->get_where('proyecto_lote_reserva',array('proyecto_lote_id'=>$id))->result_array();}
 public function ventas($id){$l=$this->get_by_id($id);if(!$l)return array();return $this->db->select('v.venta_id,v.venta_fecha,v.venta_hora,v.venta_total,v.estado_id,c.cliente_nombre')->from('detalle_venta dv')->join('venta v','v.venta_id=dv.venta_id')->join('cliente c','c.cliente_id=v.cliente_id','left')->where('dv.producto_id',$l['producto_id'])->order_by('v.venta_id','desc')->get()->result_array();}
 public function resumen($pid){$r=$this->get_by_proyecto($pid);$o=array('DISPONIBLE'=>array('cantidad'=>0,'total'=>0),'RESERVADO'=>array('cantidad'=>0,'total'=>0),'VENDIDO'=>array('cantidad'=>0,'total'=>0),'BLOQUEADO'=>array('cantidad'=>0,'total'=>0));foreach($r as $x){$e=$x['estado_actual'];if(!isset($o[$e]))$o[$e]=array('cantidad'=>0,'total'=>0);$o[$e]['cantidad']++;$o[$e]['total']+=(float)$x['precio'];}return $o;}
}
